INSERT INTO activities (title, description, category, location, country, city, rating, tags, details) VALUES
  ('Ambar', 'Ambar is a modern restaurant chain that blends Balkan tradition with creative design to offer an authentic dining experience. The menu features flavorful Serbian cuisine, including a signature unlimited plates concept and a wide selection of rakias.', 'restaurants', ST_SetSRID(ST_MakePoint(20.448128, 44.819824), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Pečat Restoran', 'Pečat Restoran is a modern Serbian establishment that offers traditional flavors prepared in a refined, contemporary way. The menu features signature dishes such as veal cooked under the bell, premium steaks, and tableside preparations.', 'restaurants', ST_SetSRID(ST_MakePoint(20.467035, 44.794228), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Kafana Pavle Korcagin', 'This traditional Serbian tavern features a socialist Yugoslavia theme and offers a wide selection of home-cooked meals and local drinks. The venue is known for having live music every night of the week and a smart casual atmosphere.', 'bars', ST_SetSRID(ST_MakePoint(20.481752, 44.803886), 4326)::geography, 'Serbia', 'Belgrade', 4.8, ARRAY['needs-review'], '{"vibe":"Relaxed, wood-paneled","happy_hour_window":"17:00-19:00","opens_time":"16:00","signature_pours":["House Rakia","Craft Lager","Negroni"]}'::jsonb),
  ('MAMA''S Bistro', 'A top-rated family-run bistro serving International and European cuisine, specializing in handmade pasta, grilled dishes, and homemade bread.', 'restaurants', ST_SetSRID(ST_MakePoint(20.453955, 44.816788), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Mezestoran Dvorište', 'This Mediterranean and European restaurant serves traditional Greek cuisine including gyros, tzatziki, and chickpea fritters in a joyful atmosphere. It features an informal setting with a refreshingly shady alfresco patio area in a central courtyard.', 'restaurants', ST_SetSRID(ST_MakePoint(20.469887, 44.812645), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Zavicaj Restaurant', 'This traditional ethno restaurant serves authentic Balkan cuisine in a rustic setting decorated with Serbian folk art and pottery.', 'restaurants', ST_SetSRID(ST_MakePoint(20.458416, 44.80938), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Curry Souls', 'Curry Souls is a modern Sri Lankan curry house serving authentic South-Asian street food in the city center of Belgrade. It is known for its flavorful dishes and vibrant atmosphere where flavor meets the heart.', 'restaurants', ST_SetSRID(ST_MakePoint(20.456873, 44.81624), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Gradska', 'Gradska is an authentic Serbian restaurant specializing in national cuisine from the Toplica district of South Serbia. It is located in a green park oasis in the heart of old Belgrade at Dorcol.', 'restaurants', ST_SetSRID(ST_MakePoint(20.46457, 44.825157), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('To Je To', 'A traditional European barbecue restaurant specializing in Sarajevo-style cuisine and authentic grilled meats like cevapcici. This family-run establishment is highly ranked for its casual atmosphere and traditional Balkan dishes.', 'restaurants', ST_SetSRID(ST_MakePoint(20.466476, 44.816853), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Tri Sesira', 'A traditional Serbian restaurant specializing in European and barbecue cuisine. It is known for its bohemian atmosphere and live traditional music.', 'restaurants', ST_SetSRID(ST_MakePoint(20.464775, 44.818123), 4326)::geography, 'Serbia', 'Belgrade', 4, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Jazz Cafe', 'A bar and cafe in Belgrade offering vegetarian-friendly, vegan, and gluten-free options for breakfast, lunch, dinner, and brunch. The venue features a jazz-themed interior with trumpet chandeliers and outdoor seating in a pedestrian area.', 'cafes', ST_SetSRID(ST_MakePoint(20.458433, 44.815544), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY['needs-review'], '{"known_for_brew":"Single-origin pour-over","wifi_quality":"Fast, plenty of outlets","hours":"08:00-22:00","on_the_bar":[{"name":"Flat White","price":"320 RSD"},{"name":"Croissant","price":"260 RSD"}]}'::jsonb),
  ('Koffein', 'Unusual coffee shop just around the corner located in a pedestrian zone of the city center. Very close to Knez Mihailova with excellent coffee selection.', 'cafes', ST_SetSRID(ST_MakePoint(20.454784, 44.817856), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY['needs-review'], '{"known_for_brew":"Single-origin pour-over","wifi_quality":"Fast, plenty of outlets","hours":"08:00-22:00","on_the_bar":[{"name":"Flat White","price":"320 RSD"},{"name":"Croissant","price":"260 RSD"}]}'::jsonb),
  ('Coffee Dream Dorćol', 'International coffee and tea spot serving breakfast, lunch, and dinner. Features include artistic coffee, cakes, frappes, ice cream, fresh squeezed juices, outdoor seating, and free wifi.', 'restaurants', ST_SetSRID(ST_MakePoint(20.461437, 44.82158), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Cafe Moskva', 'This historic Belgrade landmark is one of the oldest and best-known pastry shops in the region, famous for its signature Moskva Šnit cake and live piano performances in an elegant, traditional atmosphere.', 'restaurants', ST_SetSRID(ST_MakePoint(20.460611, 44.81296), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('NEGRO caffe', 'This unique downtown cafe serves as a quiet oasis for private conversations and features live music, cocktails, and a selection of desserts.', 'restaurants', ST_SetSRID(ST_MakePoint(20.460619, 44.813923), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Aviator Coffee Explorer', 'This central Belgrade cafe features a modern industrial interior and specializes in a wide variety of coffee origins, including Colombian and Ethiopian beans.', 'cafes', ST_SetSRID(ST_MakePoint(20.461464, 44.812428), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY['needs-review'], '{"known_for_brew":"Single-origin pour-over","wifi_quality":"Fast, plenty of outlets","hours":"08:00-22:00","on_the_bar":[{"name":"Flat White","price":"320 RSD"},{"name":"Croissant","price":"260 RSD"}]}'::jsonb),
  ('uzitak coffee selection and delights', 'This cozy cafe features a selection of finest single origin espresso and homemade products in a professional, friendly atmosphere. It is known for roasting its coffee on the spot and serving fresh juices in the heart of the city.', 'cafes', ST_SetSRID(ST_MakePoint(20.466585, 44.81534), 4326)::geography, 'Serbia', 'Belgrade', 4.8, ARRAY['needs-review'], '{"known_for_brew":"Single-origin pour-over","wifi_quality":"Fast, plenty of outlets","hours":"08:00-22:00","on_the_bar":[{"name":"Flat White","price":"320 RSD"},{"name":"Croissant","price":"260 RSD"}]}'::jsonb),
  ('Coffee Room Serbia', 'This cafe focuses on creating memorable moments for guests by offering a wide variety of high-quality sweets, macarons, and artisanal pastries.', 'cafes', ST_SetSRID(ST_MakePoint(20.455154, 44.81658), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"known_for_brew":"Single-origin pour-over","wifi_quality":"Fast, plenty of outlets","hours":"08:00-22:00","on_the_bar":[{"name":"Flat White","price":"320 RSD"},{"name":"Croissant","price":"260 RSD"}]}'::jsonb),
  ('Kafe Supa', 'Located in the heart of Belgrade, this cafe offers a warm atmosphere with an unusual blend of vintage and industrial interior.', 'cafes', ST_SetSRID(ST_MakePoint(20.454618, 44.814114), 4326)::geography, 'Serbia', 'Belgrade', 4.8, ARRAY['needs-review'], '{"known_for_brew":"Single-origin pour-over","wifi_quality":"Fast, plenty of outlets","hours":"08:00-22:00","on_the_bar":[{"name":"Flat White","price":"320 RSD"},{"name":"Croissant","price":"260 RSD"}]}'::jsonb),
  ('Cafe&Factory', 'This specialty cafe is known for roasting its own beans and offering a wide variety of international coffees in a central pedestrian location. It features a popular outdoor seating area and is highly rated for its professional service and fresh coffee quality.', 'cafes', ST_SetSRID(ST_MakePoint(20.460758, 44.785217), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"known_for_brew":"Single-origin pour-over","wifi_quality":"Fast, plenty of outlets","hours":"08:00-22:00","on_the_bar":[{"name":"Flat White","price":"320 RSD"},{"name":"Croissant","price":"260 RSD"}]}'::jsonb),
