  ('Spasicev Pub Belgrade', 'Fun place to experience local life with good selection of draft beers, food, live music and sports on TV.', 'bars', ST_SetSRID(ST_MakePoint(20.454847, 44.81853), 4326)::geography, 'Serbia', 'Belgrade', 4.2, ARRAY['needs-review'], '{"vibe":"Relaxed, wood-paneled","happy_hour_window":"17:00-19:00","opens_time":"16:00","signature_pours":["House Rakia","Craft Lager","Negroni"]}'::jsonb),
