  ('Dogma Brewery', 'Small batch craft brewery dedicated to making special hoppy ales with a great tap room atmosphere.', 'bars', ST_SetSRID(ST_MakePoint(20.465, 44.8125), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY['needs-review'], '{"vibe":"Relaxed, wood-paneled","happy_hour_window":"17:00-19:00","opens_time":"16:00","signature_pours":["House Rakia","Craft Lager","Negroni"]}'::jsonb),
  ('Koi Bar • Sushi And Cocktail', 'Vibrant and trendy spot in Skadarlija district offering exquisite sushi and expertly crafted cocktails for an upscale experience.', 'restaurants', ST_SetSRID(ST_MakePoint(20.463495, 44.81676), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('Hype', 'First luxury and high class club in Belgrade featuring the latest lighting and sound system, playing House, tech house, funky, disco, R''n''B and hits from 80''s, 90''s.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4473, 44.8083), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY['needs-review'], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('The Bank Club', 'First Premium RnB club in this part of Europe with high level service, located at the most exclusive place in Belgrade at Beton Hala.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4475, 44.8177), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY['needs-review'], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('Gatsby', 'Club-type facility at the mouth of Sava and Danube rivers with extremely pleasant ambiance and exceptional equipment, operating with live bands and DJs.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4564, 44.8233), 4326)::geography, 'Serbia', 'Belgrade', 4.8, ARRAY['needs-review'], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('Club 20/44', 'Floating club vessel on the Sava river with an undergroundish but friendly vibe, offering an authentic Belgrade party experience.', 'nightlife', ST_SetSRID(ST_MakePoint(20.445, 44.815), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('Freestyler Belgrade Nightclub', 'Legendary floating club on the river operating for over 20 years, welcoming top international DJs and a fun, stylish crowd from all over the world.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4055, 44.8518), 4326)::geography, 'Serbia', 'Belgrade', 3.6, ARRAY[]::TEXT[], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('Splav TAG Belgrade Nightclub', 'Riverbank nightclub with state-of-the-art sound systems, mesmerizing light shows, dancers and performers, featuring spectacular performances and dynamic dance floor.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4319, 44.8189), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('Leto Belgrade', 'Summer club at the spot where Sava River meets the Danube with stunning view of Kalemegdan Fortress, gathering urban lovers of quality electronic beats.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4564, 44.8233), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY['needs-review'], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('KULT', 'Underground club with capacity of 300 people featuring flawless Funktion-One sound system, playing house, deep house, progressive house, tech house, minimal, and techno. Age limit 23+.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4567, 44.817), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY['needs-review'], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('Money Club', 'First Summer RnB Club in Belgrade with great summer vibe, beautiful interior, and crazy cocktails. Entry is free, age limit 23+, dress code elegant or smart casual.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4319, 44.8189), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY['needs-review'], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('Drugstore Club Beograd', 'Underground techno club in a former meat factory space, perfect for those who like dark techno music and partying in a more shady environment.', 'nightlife', ST_SetSRID(ST_MakePoint(20.465, 44.82), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY['needs-review'], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('Ada Ciganlija', 'A beloved river island turned peninsula featuring pristine nature, biking trails, rowing, running facilities, and beach areas along the Sava River.', 'nature', ST_SetSRID(ST_MakePoint(20.4, 44.7833), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY['needs-review'], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Kalemegdan Park and Belgrade Fortress', 'Historic fortress park perched at the confluence of the Sava and Danube rivers, featuring walking paths, monuments, and panoramic views from 125 meters above sea level.', 'nature', ST_SetSRID(ST_MakePoint(20.451, 44.824421), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Košutnjak Hill', 'A sprawling green forest oasis with dense tree canopy, winding walking trails, and abundant picnic areas, popular for relaxation and family gatherings.', 'nature', ST_SetSRID(ST_MakePoint(20.435, 44.76667), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY['needs-review'], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Mountain Avala', 'A hiking destination featuring a well-prepared 1700-meter route to the summit, with an iconic TV tower offering panoramic views and a coffee shop.', 'cafes', ST_SetSRID(ST_MakePoint(20.51602, 44.68902), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY['needs-review'], '{"known_for_brew":"Single-origin pour-over","wifi_quality":"Fast, plenty of outlets","hours":"08:00-22:00","on_the_bar":[{"name":"Flat White","price":"320 RSD"},{"name":"Croissant","price":"260 RSD"}]}'::jsonb),
  ('Topčider Park', 'One of Belgrade''s oldest parks featuring diverse trees, fresh air, historic sites including Peter and Paul church, and a 200-year-old London plane tree.', 'nature', ST_SetSRID(ST_MakePoint(20.4595, 44.7736), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Great War Island', 'A wild river island at the confluence of Sava and Danube, featuring Lido Beach on its northern tip and accessible via pontoon bridge in summer.', 'nature', ST_SetSRID(ST_MakePoint(20.43, 44.85), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY['needs-review'], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Tašmajdan Park', 'A large urban park in the city center with many walking paths, monuments dedicated to important Serbian historical figures, and beautiful green spaces.', 'nature', ST_SetSRID(ST_MakePoint(20.47076, 44.81008), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Zemunski Park', 'A historic seven-hectare park in the heart of Zemun''s old core, established in 1880, featuring sports facilities, schools, and flanked by Orthodox and Catholic churches.', 'nature', ST_SetSRID(ST_MakePoint(20.403, 44.843), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY['needs-review'], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Jevremovac Botanical Garden', 'A small botanical garden in central Belgrade featuring a renovated greenhouse, diverse plant collections, and old trees providing a peaceful retreat.', 'nature', ST_SetSRID(ST_MakePoint(20.47322, 44.81581), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY['needs-review'], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Belgrade Zoo', 'One of the oldest zoos in Southeastern Europe, located in Kalemegdan Park, home to around 800 animals representing 210 species including white wolves and hippos.', 'nature', ST_SetSRID(ST_MakePoint(20.45333, 44.82583), 4326)::geography, 'Serbia', 'Belgrade', 3.7, ARRAY['needs-review'], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
