  ('Climbing Gym Gekon', 'Old-school climbing gym with welcoming community and top-notch coaching, featuring 18m indoor wall for rope climbing.', 'sport', ST_SetSRID(ST_MakePoint(20.465, 44.8214), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY['needs-review'], '{"difficulty":2,"effort_level":"Moderate","duration":"1-2 hours","gear":"Equipment available on site","what_to_bring":["Water bottle","Sportswear"]}'::jsonb),
  ('Belgrade Zoo', 'A city zoo featuring a collection of animals including white tigers, Bengal tigers, lions, polar wolves, hippos, and a famous crocodile that has lived there since 1937. It includes a petting zoo area where children can feed goats.', 'kids', ST_SetSRID(ST_MakePoint(20.4533, 44.82583), 4326)::geography, 'Serbia', 'Belgrade', 3.7, ARRAY['needs-review'], '{"age_range":"All ages","facilities":["Baby changing rooms","Playground","Picnic area"]}'::jsonb),
  ('Museum of Illusions', 'A fascinating world of illusions featuring over 70 interactive exhibits that are both educational and entertaining for families, offering visual trickery and perspective-based puzzles.', 'culture', ST_SetSRID(ST_MakePoint(20.4569, 44.8169), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
  ('Nikola Tesla Museum', 'A science museum dedicated to the life and legacy of inventor Nikola Tesla with guided tours that include demonstrations of his experiments, appealing to families and science enthusiasts.', 'culture', ST_SetSRID(ST_MakePoint(20.4707, 44.8051), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY['needs-review'], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
  ('Public Aquarium and Tropicarium Belgrade', 'A gathering place for children and families to see aquatic and tropical ecosystems from around the world, featuring biotopes of local and international rivers, seas, and lakes along with reptiles, mammals and insects.', 'bars', ST_SetSRID(ST_MakePoint(20.4695, 44.8142), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY['needs-review'], '{"vibe":"Relaxed, wood-paneled","happy_hour_window":"17:00-19:00","opens_time":"16:00","signature_pours":["House Rakia","Craft Lager","Negroni"]}'::jsonb),
  ('Dino Park Jura Avantura', 'A dinosaur-themed park featuring life-size dinosaur models and interactive exhibits, perfect for young children who enjoy prehistoric creatures. Located within the historic Belgrade Fortress.', 'nature', ST_SetSRID(ST_MakePoint(20.45, 44.8236), 4326)::geography, 'Serbia', 'Belgrade', 3.3, ARRAY['needs-review'], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Playroom Mia', 'A combined children''s playroom and modern cafeteria featuring a climbing wall, slides, trampolines, and toys for kids, while offering a space for parents to relax with coffee and local food.', 'kids', ST_SetSRID(ST_MakePoint(20.4083, 44.8534), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"age_range":"All ages","facilities":["Baby changing rooms","Playground","Picnic area"]}'::jsonb),
  ('Selfie Museum Expose', 'An interactive exhibition with 27 unique attractions across 500 square meters featuring themed rooms perfect for creative photos, designed for families and those who enjoy fun, memorable experiences.', 'culture', ST_SetSRID(ST_MakePoint(20.4648, 44.8073), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY['needs-review'], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
  ('Museum of Science and Technology', 'A museum showcasing technical history with three levels of exhibitions including industrial equipment, vintage cameras, early computing relics, and a children''s department with interactive activities and workshops adapted for younger visitors.', 'kids', ST_SetSRID(ST_MakePoint(20.4678, 44.8311), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY['needs-review'], '{"age_range":"All ages","facilities":["Baby changing rooms","Playground","Picnic area"]}'::jsonb),
  ('Skakaonica AVA PARK', 'A 4,800 square meter trampoline park offering over 30 unique attractions including climbing walls, free jump arena, ninja warrior course, ropes course, and specialized toddler areas with soft play zones.', 'kids', ST_SetSRID(ST_MakePoint(20.3845, 44.7893), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"age_range":"All ages","facilities":["Baby changing rooms","Playground","Picnic area"]}'::jsonb),
  ('Igraj.rs Kids Playground - Ada Mall', 'A 350 square meter rooftop kids center with glass architecture featuring age-specific zones for children 3-12, including soft play areas, ball pits, space-themed 3D maze, zip lines, trampolines, and educational workshops.', 'kids', ST_SetSRID(ST_MakePoint(20.414, 44.7869), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"age_range":"All ages","facilities":["Baby changing rooms","Playground","Picnic area"]}'::jsonb),
  ('Belgrade Fortress', 'This historic fortress is located at the highest point of the city overlooking the confluence of the Sava and Danube Rivers. Today, the fortress grounds serve as a spacious city park featuring historic gates, ramparts, and the Serbian Military Museum.', 'nature', ST_SetSRID(ST_MakePoint(20.4497647, 44.8235022), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Church of Saint Sava', 'One of the largest Orthodox temples in the world, this landmark features a magnificent interior covered in golden mosaics and is inspired by the Hagia Sophia in Istanbul.', 'culture', ST_SetSRID(ST_MakePoint(20.469116, 44.7981), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY['needs-review'], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
  ('Republic Square', 'A central square in Belgrade surrounded by the National Museum and National Theatre. It serves as a popular meeting point and hub for shopping, dining, and people watching.', 'restaurants', ST_SetSRID(ST_MakePoint(20.460111, 44.816444), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY['needs-review'], '{"cuisine":"Local \u0026 European","price_tier":"$$","hours":"11:00-23:00","open_status":"Open now","popular_dishes":[{"name":"Chef''s Platter","price":"1200 RSD"},{"name":"Grilled Catch of the Day","price":"1600 RSD"}]}'::jsonb),
  ('St. Mark''s Church', 'A grand Serbian-Byzantine style church built between 1931 and 1940, located within the Tašmajdan Park. It is recognized as a cultural monument and known for its striking architecture.', 'nature', ST_SetSRID(ST_MakePoint(20.4685, 44.8101), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY['needs-review'], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('National Museum Belgrade', 'The oldest and largest museum in Serbia, featuring extensive archaeological collections from ancient times and a significant art collection with works by masters like Picasso, Monet, and Renoir.', 'culture', ST_SetSRID(ST_MakePoint(20.4594, 44.8167), 4326)::geography, 'Serbia', 'Belgrade', 4.1, ARRAY['needs-review'], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
  ('Nebojša Tower', 'A late 14th-century historical monument and well-preserved tower located in the lower part of the Belgrade Fortress. It originally served as a defensive structure and currently houses a multimedia museum.', 'culture', ST_SetSRID(ST_MakePoint(20.451, 44.8215), 4326)::geography, 'Serbia', 'Belgrade', 4, ARRAY[]::TEXT[], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
  ('Residence of Princess Ljubica', 'This museum showcases 19th-century living for an affluent family in Belgrade, featuring an evolution of interior styles from Ottoman to Central European. The residence was built around 1830 for Princess Ljubica Obrenovic.', 'culture', ST_SetSRID(ST_MakePoint(20.45227, 44.81712), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY['needs-review'], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
  ('Bajrakli Mosque', 'This 16th-century Ottoman building is the only remaining mosque in Belgrade. It features a classic square design with a single dome and minaret and remains an active place of worship.', 'culture', ST_SetSRID(ST_MakePoint(20.4575, 44.8222), 4326)::geography, 'Serbia', 'Belgrade', 4, ARRAY['needs-review'], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
  ('Ružica Church', 'A historic Serbian Orthodox church located within the Belgrade Fortress, famous for its unique chandeliers made from military weapons and its beautiful interior frescoes.', 'culture', ST_SetSRID(ST_MakePoint(20.449, 44.8235), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY['needs-review'], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
  ('Saint Petka''s Chapel', 'This small Orthodox sanctuary is located within the Belgrade Fortress and is renowned for its vibrant interior mosaics and peaceful atmosphere. It was built in 1937 on the site of a miraculous spring.', 'shopping', ST_SetSRID(ST_MakePoint(20.4495, 44.8238), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY['needs-review'], '{"venue_type":"Retail","best_day":"Saturday","hours":"10:00-21:00","what_youll_find":["Local boutiques","Cafés","Souvenir shops"]}'::jsonb),
  ('National Museum Belgrade', 'A large museum featuring a famous collection of European art including works by Picasso, Monet, and Renoir, as well as ancient artifacts.', 'culture', ST_SetSRID(ST_MakePoint(20.4598, 44.8166), 4326)::geography, 'Serbia', 'Belgrade', 4.1, ARRAY['needs-review'], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
